def conform():
    from bookflow.company import schema as c, deposit_dependency_history as h, deposit_sources as sources
    from bookflow.company.deposit_read_facts import TABLES
    from bookflow.company import deposit_models as m, deposit_lifecycle_models as l, deposit_coordinate_models as co, deposit_draft_models as d
    from bookflow.company.deposit_read_models import Issuer
    from bookflow.company.journal_custom_fields import SnapshotField
    def require(ok):
        if not ok:raise BookflowError('E_DEPOSIT_SOURCE_INVALID')
    require(h._IMMUTABLE==IMMUTABLE_OWNERS and sources.TABLES==SOURCE_TABLES and TABLES==DEPOSIT_TABLES)
    require(set(FIELDS)==set(EDGES)==set(REQUIRED_TABLES))
    require(set(TABLES)|{x[0] for x in h._IMMUTABLE}|set(sources.TABLES)<=set(FIELDS))
    for name,fields in FIELDS.items():
        table=c.metadata.tables[name]
        require(set(fields)==set(table.c.keys()))
        require(all((col.type.python_type.__name__,col.nullable,col.primary_key)==fields[col.name][:3] and fields[col.name][3] for col in table.c))
        edges=sorted((tuple(f.column_keys),tuple(e.target_fullname for e in f.elements)) for f in table.foreign_key_constraints)
        require(edges==EDGES[name])
    models=(m.Effect,l.LifecycleOutput,co.CoordinateOutput,d.Manifest,Issuer,SnapshotField)
    require(set(CODECS)=={x.__name__ for x in models})
    for model in models:
        require(hashlib.sha256(json.dumps(model.model_json_schema(),sort_keys=True).encode()).hexdigest()==CODECS[model.__name__])
